"use client"

import { useState } from "react"
import { Search, GraduationCap, Briefcase, ExternalLink, ArrowRight, Zap, Target } from "lucide-react"
import { motion, AnimatePresence } from "framer-motion"
import { apiUrl } from "@/lib/api-url"
import { useRouter } from "next/navigation"
import Link from "next/link"

interface Paper {
    title: string
    url: string
    source: string
    type?: string
    googleFallback?: string
}

interface CareerStats {
    companies: string[]
    roles: string[]
    marketDemand: number
    summary: string
}

export default function CareerVaultUI() {
    const [institution, setInstitution] = useState("")
    const [grade, setGrade] = useState("")
    const [subject, setSubject] = useState("")
    const [loading, setLoading] = useState(false)
    const [results, setResults] = useState<{ papers: Paper[]; career: CareerStats } | null>(null)
    const router = useRouter()

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault()
        if (!institution || !grade || !subject) return

        setLoading(true)
        try {
            const response = await fetch(apiUrl("/api/papers/discover"), {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ institution, grade, subject }),
            })
            const data = await response.json()
            setResults(data)
        } catch (error) {
            console.error("Search failed:", error)
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="max-w-6xl mx-auto px-4 py-12">
            {/* Header section */}
            <div className="text-center mb-12">
                <motion.div
                    initial={{ opacity: 0, y: -20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/20 text-blue-400 text-xs font-mono mb-4"
                >
                    <Zap className="w-3 h-3" />
                    THE QUESTION VAULT
                </motion.div>
                <h1 className="text-4xl md:text-5xl font-bold tech-heading mb-4 gradient-text">
                    Master Your Exams, <br />Launch Your Career
                </h1>
                <p className="text-slate-400 max-w-2xl mx-auto">
                    Find real past papers and see how every chapter you study connects to high-paying jobs in the industry.
                </p>
            </div>

            {/* Search Form */}
            <div className="tech-card p-6 mb-12 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/5 blur-3xl -z-10" />
                <form onSubmit={handleSearch} className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="space-y-2">
                        <label className="text-xs font-mono text-slate-500 uppercase tracking-wider">Institution / Board</label>
                        <input
                            type="text"
                            placeholder="e.g. CBSE, ICSE, VTU"
                            value={institution}
                            onChange={(e) => setInstitution(e.target.value)}
                            className="w-full bg-slate-900/50 border border-slate-800 rounded-lg px-4 py-3 text-sm focus:border-blue-500/50 outline-none transition-colors"
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-xs font-mono text-slate-500 uppercase tracking-wider">Class / Sem / Grade</label>
                        <input
                            type="text"
                            placeholder="e.g. 12th, 3rd Sem"
                            value={grade}
                            onChange={(e) => setGrade(e.target.value)}
                            className="w-full bg-slate-900/50 border border-slate-800 rounded-lg px-4 py-3 text-sm focus:border-blue-500/50 outline-none transition-colors"
                        />
                    </div>
                    <div className="space-y-2">
                        <label className="text-xs font-mono text-slate-500 uppercase tracking-wider">Subject</label>
                        <input
                            type="text"
                            placeholder="e.g. Physics, Data Structures"
                            value={subject}
                            onChange={(e) => setSubject(e.target.value)}
                            className="w-full bg-slate-900/50 border border-slate-800 rounded-lg px-4 py-3 text-sm focus:border-blue-500/50 outline-none transition-colors"
                        />
                    </div>
                    <div className="flex items-end">
                        <button
                            disabled={loading}
                            className="w-full tech-button-primary h-[46px] flex items-center justify-center gap-2 group disabled:opacity-50"
                        >
                            {loading ? (
                                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                            ) : (
                                <>
                                    <Search className="w-4 h-4 group-hover:scale-110 transition-transform" />
                                    DISCOVER NOW
                                </>
                            )}
                        </button>
                    </div>
                </form>
            </div>

            <AnimatePresence mode="wait">
                {results && (
                    <motion.div
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -20 }}
                        className="grid grid-cols-1 lg:grid-cols-3 gap-8"
                    >
                        {/* Real Papers Section */}
                        <div className="lg:col-span-2 space-y-6">
                            <h3 className="text-xl font-bold tech-heading flex items-center gap-2">
                                <GraduationCap className="w-5 h-5 text-blue-400" />
                                Discovered Past Papers
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {results.papers.map((paper, idx) => (
                                    <motion.div
                                        key={idx}
                                        initial={{ opacity: 0, x: -20 }}
                                        animate={{ opacity: 1, x: 0 }}
                                        transition={{ delay: idx * 0.1 }}
                                        className="tech-card p-4 hover:border-blue-500/30 transition-all group"
                                    >
                                        <div className="flex justify-between items-start mb-2">
                                            <div className="flex gap-2 items-center">
                                                <div className="p-2 rounded bg-blue-500/10 text-blue-400">
                                                    <Target className="w-4 h-4" />
                                                </div>
                                                {paper.type && (
                                                    <span className={`text-[9px] font-mono px-1.5 py-0.5 rounded border ${paper.type === 'Direct PDF' ? 'border-blue-500/20 text-blue-400 bg-blue-500/5' : 'border-slate-700 text-slate-500 uppercase'}`}>
                                                        {paper.type}
                                                    </span>
                                                )}
                                            </div>
                                            <span className="text-[10px] font-mono text-slate-500">{paper.source}</span>
                                        </div>
                                        <h4 className="font-semibold text-slate-200 mb-4 group-hover:text-blue-400 transition-colors">
                                            {paper.title}
                                        </h4>
                                        <div className="flex flex-col gap-2">
                                            <div className="flex items-center gap-3">
                                                <a
                                                    href={paper.url}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="flex-1 tech-button py-2 text-xs flex items-center justify-center gap-2"
                                                >
                                                    <ExternalLink className="w-3 h-3" />
                                                    {paper.type === 'Direct PDF' ? 'VIEW PDF' : 'OPEN PORTAL'}
                                                </a>
                                                <button
                                                    onClick={() => router.push(`/pathways?subject=${encodeURIComponent(subject)}&topic=${encodeURIComponent(paper.title)}`)}
                                                    className="flex-1 tech-button-primary py-2 text-xs flex items-center justify-center gap-2"
                                                >
                                                    <Zap className="w-3 h-3" />
                                                    ANALYZE
                                                </button>
                                            </div>
                                            {paper.googleFallback && (
                                                <a
                                                    href={paper.googleFallback}
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                    className="text-[10px] text-center text-slate-500 hover:text-blue-400 transition-colors py-1 border border-dashed border-slate-800 rounded flex items-center justify-center gap-2"
                                                >
                                                    <Search className="w-3 h-3" />
                                                    Broken Link? Search on Google
                                                </a>
                                            )}
                                        </div>
                                    </motion.div>
                                ))}
                            </div>
                        </div>

                        {/* Industry Relevance Section */}
                        <div className="space-y-6">
                            <h3 className="text-xl font-bold tech-heading flex items-center gap-2">
                                <Briefcase className="w-5 h-5 text-emerald-400" />
                                Industry Relevance
                            </h3>
                            <div className="tech-card p-6 space-y-6 border-emerald-500/20 bg-emerald-500/5">
                                {/* Market Demand Gauge */}
                                <div>
                                    <div className="flex justify-between items-center mb-2">
                                        <span className="text-xs font-mono text-slate-400">MARKET DEMAND</span>
                                        <span className="text-lg font-bold text-emerald-400">{results.career.marketDemand}%</span>
                                    </div>
                                    <div className="h-2 bg-slate-800 rounded-full overflow-hidden">
                                        <motion.div
                                            initial={{ width: 0 }}
                                            animate={{ width: `${results.career.marketDemand}%` }}
                                            className="h-full bg-gradient-to-r from-emerald-600 to-emerald-400"
                                        />
                                    </div>
                                </div>

                                {/* Roles & Companies */}
                                <div className="space-y-4">
                                    <div>
                                        <span className="text-[10px] font-mono text-slate-500 block mb-2 tracking-widest uppercase">Target Job Roles</span>
                                        <div className="flex flex-wrap gap-2">
                                            {results.career.roles.map((role, idx) => (
                                                <span key={idx} className="px-2 py-1 rounded bg-slate-800 text-[11px] text-slate-300 border border-slate-700">
                                                    {role}
                                                </span>
                                            ))}
                                        </div>
                                    </div>
                                    <div>
                                        <span className="text-[10px] font-mono text-slate-500 block mb-2 tracking-widest uppercase">Hiring Powerhouses</span>
                                        <div className="flex flex-wrap gap-2">
                                            {results.career.companies.map((company, idx) => (
                                                <span key={idx} className="px-2 py-1 rounded bg-emerald-500/10 text-[11px] text-emerald-400 border border-emerald-500/20">
                                                    {company}
                                                </span>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                <div className="pt-4 border-t border-slate-800">
                                    <p className="text-xs italic text-slate-400 leading-relaxed italic">
                                        "{results.career.summary}"
                                    </p>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    )
}
